import type { Activity, ActivityCategory, ActivitySkill, ActivityType } from '../types/models'

const makeActivity = (
  id: string,
  title: string,
  description: string,
  category: ActivityCategory,
  skill: ActivitySkill,
  ageMin: number,
  ageMax: number,
  duration: number,
  materials: string[],
  instructions: string[],
  parentTip: string,
  benefits: string[],
  safetyNotesOrVariations?: string[] | number,
  variationsOrCooldown?: string[] | number,
  repeatCooldownDays = 2,
  activityType: ActivityType = 'guided',
): Activity => {
  const safetyNotes = Array.isArray(safetyNotesOrVariations) ? safetyNotesOrVariations : []
  const variations = Array.isArray(variationsOrCooldown) ? variationsOrCooldown : []
  const cooldown = typeof safetyNotesOrVariations === 'number'
    ? safetyNotesOrVariations
    : typeof variationsOrCooldown === 'number'
      ? variationsOrCooldown
      : repeatCooldownDays

  return {
    id,
    title,
    description,
    category,
    skill,
    ageMin,
    ageMax,
    duration,
    materials,
    instructions,
    parentTip,
    benefits,
    difficulty: 'easy',
    safetyNotes,
    variations,
    repeatCooldownDays: cooldown,
    activityType,
    completed: false,
    isPremium: false,
  }
}

